// #6a993d795019333734edc22d (#edc22d) AC5, треб.3 — нет самостоятельной регистрации бизнеса (кейс BIZ-LC-008).
// spec: specs/business-lifecycle.md (5.1) · seed: tests/seed.spec.ts (гость). Только чтение — @prod-safe.
import { test, expect } from '../../fixtures';

test.describe('Нет самостоятельной регистрации (#6a993d795019333734edc22d)', () => {
  test('гость: /signup, /register, /join, /admin/businesses/new → вход, регистрации нет @desktop @prod-safe #6a993d795019333734edc22d', async ({ page }) => {
    // AC5 «לא קיים מסך או נתיב המאפשר זאת».
    for (const url of ['/signup', '/register', '/join', '/admin/businesses/new']) {
      await page.goto(url);
      await page.waitForURL((u) => u.pathname === '/login');
      await expect(page.getByRole('heading', { level: 1, name: 'כניסה לחשבון' }), url).toBeVisible();
      await expect(page.getByRole('textbox', { name: 'שם העסק (חובה)' }), url).toHaveCount(0);
      await expect(page.getByRole('button', { name: 'יצירת בית העסק' }), url).toHaveCount(0);
    }

    // Треб.3: на /login нет ни ссылки, ни кнопки регистрации; есть пояснение «только по приглашению».
    for (const name of [/הרשמה/, /יצירת חשבון/]) {
      await expect(page.getByRole('link', { name })).toHaveCount(0);
      await expect(page.getByRole('button', { name })).toHaveCount(0);
    }
    await expect(page.getByText('הכניסה בהזמנה בלבד. אין לכם חשבון? בקשו הזמנה ממנהל החשבון בעסק.')).toBeVisible();
  });
});
